/*
 * The game data in RAM: tmc/gamedata.bin, made once from the player's ROM, then
 * relocation (port/dsi/PLAN.md, "ROM loading and relocation at boot").
 */

#include <nds.h>
#include <fat.h>
#include <nds/arm9/exceptions.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "dsi.h"

// rom_relocs.s, generated by port/dsi/tools/gen_link.py. The copy holds the
// extents back to back; the offset lists are byte deltas in halfwords, where 0
// escapes a 32-bit delta.
typedef struct {
    uint32_t rom;    // offset from DSI_ROM_BASE
    uint32_t length;
    uint32_t copy;   // offset from __rom_copy
} RomExtent;

extern const uint32_t gRomLayoutVersion[2];
extern const uint32_t gRomExtentCount;
extern const RomExtent gRomExtents[];
extern const uint32_t gRomRelocAddCount;
extern const uint32_t gRomRelocSymbolCount;
extern const uint32_t gRomRelocKeptCount;
extern const uint32_t gRomRelocSymbols[]; // (offset, value) pairs
extern const uint16_t gRomRelocAdds[], gRomRelocAddsEnd[];
extern const uint16_t gRomRelocKept[], gRomRelocKeptEnd[];

#define ROM_FILE_SIZE 0x1000000
#define ROM_CHUNK 0x20000
#define EWRAM_BASE 0x02000000u
#define EWRAM_SIZE 0x40000u
#define IWRAM_BASE 0x03000000u

// The copy's bytes as read from the ROM, before relocation. The header is a
// sector, so the data reads straight into the copy.
#define GAMEDATA_MAGIC "TMCDSI"
#define GAMEDATA_FORMAT 1
#define GAMEDATA_HEADER_SIZE 512

typedef struct {
    char magic[8];
    uint32_t format;
    uint32_t headerSize;
    uint32_t layout[2]; // gRomLayoutVersion of the build that wrote it
    uint32_t dataSize;
    uint8_t romSha1[20];
} GameDataHeader;

// The DSi SD slot first; DLDI (fat:) for flashcards and melonDS tests. The
// boot log and the save go next to the game data.
static const char* const sDataPaths[] = { "sd:/tmc/gamedata.bin", "fat:/tmc/gamedata.bin" };
static const char* const sDataTempPaths[] = { "sd:/tmc/gamedata.tmp", "fat:/tmc/gamedata.tmp" };
static const char* const sRomPaths[] = { "sd:/tmc/baserom.gba", "fat:/tmc/baserom.gba" };
static const char* const sLogPaths[] = { "sd:/tmc/boot.txt", "fat:/tmc/boot.txt" };
static const char* const sSavePaths[] = { "sd:/tmc/tmc.sav", "fat:/tmc/tmc.sav" };
#define CARDS (sizeof(sDataPaths) / sizeof(sDataPaths[0]))
static const char* sSavePath;

const char* DsiSavePath(void) {
    return sSavePath;
}

// The USA ROM, as port/README.md.
static const uint8_t sUsaSha1[20] = {
    0xb4, 0xbd, 0x50, 0xe4, 0x13, 0x1b, 0x02, 0x7c, 0x33, 0x45,
    0x47, 0xb4, 0x52, 0x4e, 0x2d, 0xbb, 0xd4, 0x22, 0x71, 0x30,
};

static void HexDigest(char* out, const uint8_t* digest) {
    for (int i = 0; i < 20; i++) {
        sprintf(out + 2 * i, "%02x", digest[i]);
    }
}

static void UseCard(size_t card) {
    sSavePath = sSavePaths[card];
    DsiLogToFile(sLogPaths[card]);
}

// The extent holding GBA ROM offset, which may be its end, or NULL.
static const RomExtent* FindExtent(uint32_t offset) {
    uint32_t lo = 0, hi = gRomExtentCount;

    while (lo < hi) { // the first extent starting after offset
        uint32_t mid = (lo + hi) / 2;
        if (gRomExtents[mid].rom <= offset) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo == 0 || offset - gRomExtents[lo - 1].rom > gRomExtents[lo - 1].length) {
        return NULL;
    }
    return &gRomExtents[lo - 1];
}

uint8_t* DsiRomPtr(uint32_t address) {
    uint32_t offset = address - DSI_ROM_BASE;
    const RomExtent* e;

    if (offset >= 0x02000000u || (e = FindExtent(offset)) == NULL) {
        return NULL;
    }
    return __rom_copy + e->copy + (offset - e->rom);
}

uint32_t DsiRomAddress(const void* pointer) {
    uint32_t offset = (const uint8_t*)pointer - __rom_copy;
    uint32_t lo = 0, hi = gRomExtentCount;

    if ((const uint8_t*)pointer < __rom_copy || (const uint8_t*)pointer >= __rom_copy_end) {
        return 0;
    }
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        if (gRomExtents[mid].copy <= offset) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo == 0 || offset - gRomExtents[lo - 1].copy > gRomExtents[lo - 1].length) {
        return 0; // the padding between two extents
    }
    return DSI_ROM_BASE + gRomExtents[lo - 1].rom + (offset - gRomExtents[lo - 1].copy);
}

typedef enum {
    DATA_OK,
    DATA_NONE,
    DATA_STALE, // from a build with other extents
    DATA_BAD,
} DataResult;

static DataResult LoadGameData(const char* path) {
    uint32_t size = __rom_copy_end - __rom_copy;
    GameDataHeader header;
    char hex[41];
    FILE* file;

    file = fopen(path, "rb");
    if (file == NULL) {
        return DATA_NONE;
    }
    setvbuf(file, NULL, _IONBF, 0);
    if (fread(&header, 1, sizeof(header), file) != sizeof(header) ||
        memcmp(header.magic, GAMEDATA_MAGIC, sizeof(GAMEDATA_MAGIC)) != 0 || header.format != GAMEDATA_FORMAT ||
        header.headerSize < sizeof(header) || memcmp(header.romSha1, sUsaSha1, sizeof(sUsaSha1)) != 0) {
        DsiLog("%s is damaged\n", path);
        fclose(file);
        return DATA_BAD;
    }
    if (header.layout[0] != gRomLayoutVersion[0] || header.layout[1] != gRomLayoutVersion[1] ||
        header.dataSize != size) {
        DsiLog("%s is from a build with other game data (%08lx%08lx, this one %08lx%08lx)\n", path,
               (unsigned long)header.layout[1], (unsigned long)header.layout[0],
               (unsigned long)gRomLayoutVersion[1], (unsigned long)gRomLayoutVersion[0]);
        fclose(file);
        return DATA_STALE;
    }
    cpuStartTiming(0);
    if (fseek(file, header.headerSize, SEEK_SET) != 0) {
        cpuEndTiming();
        DsiLog("%s is damaged\n", path);
        fclose(file);
        return DATA_BAD;
    }
    for (uint32_t pos = 0; pos < size;) {
        uint32_t length = size - pos < ROM_CHUNK ? size - pos : ROM_CHUNK;

        if (fread(__rom_copy + pos, 1, length, file) != length) {
            cpuEndTiming();
            DsiLog("%s is incomplete (%lu of %lu bytes)\n", path, (unsigned long)pos, (unsigned long)size);
            fclose(file);
            return DATA_BAD;
        }
        pos += length;
    }
    DsiLog("read %lu bytes of game data from %s in %lu ms\n", (unsigned long)size, path,
           (unsigned long)timerTicks2msec(cpuEndTiming()));
    fclose(file);
    HexDigest(hex, header.romSha1);
    DsiLog("SHA-1 %s (when it was made)\n", hex);
    return DATA_OK;
}

/*
 * One pass over the ROM: every chunk is hashed (sha1.c) and the extents' parts
 * of it go to the copy. The padding between extents stays zero, so the copy
 * and its CRC are the same whichever way it was loaded.
 */
static bool ReadRom(FILE* file, const char* path, uint8_t* digest) {
    uint32_t readTicks = 0, hashTicks = 0, total;
    const RomExtent* e = gRomExtents;
    const RomExtent* end = gRomExtents + gRomExtentCount;
    uint8_t* scratch;
    DsiSha1 sha;
    char hex[41];
    long size;

    fseek(file, 0, SEEK_END);
    size = ftell(file);
    fseek(file, 0, SEEK_SET);
    if (size != ROM_FILE_SIZE) {
        DsiLog("%s is %ld bytes, expected %d\n", path, size, ROM_FILE_SIZE);
        return false;
    }
    scratch = malloc(ROM_CHUNK);
    if (scratch == NULL) {
        DsiLog("no memory for the read buffer\n");
        return false;
    }
    setvbuf(file, NULL, _IONBF, 0);
    memset(__rom_copy, 0, __rom_copy_end - __rom_copy);

    DsiSha1Init(&sha);
    cpuStartTiming(0);
    for (uint32_t pos = 0; pos < ROM_FILE_SIZE; pos += ROM_CHUNK) {
        uint32_t t0, t1;

        t0 = cpuGetTiming();
        if (fread(scratch, 1, ROM_CHUNK, file) != ROM_CHUNK) {
            DsiLog("read error at 0x%06lx in %s\n", (unsigned long)pos, path);
            cpuEndTiming();
            free(scratch);
            return false;
        }
        t1 = cpuGetTiming();
        DsiSha1Update(&sha, scratch, ROM_CHUNK);
        for (; e < end && e->rom < pos + ROM_CHUNK; e++) {
            uint32_t from = e->rom > pos ? e->rom : pos;
            uint32_t to = e->rom + e->length < pos + ROM_CHUNK ? e->rom + e->length : pos + ROM_CHUNK;

            memcpy(__rom_copy + e->copy + (from - e->rom), scratch + (from - pos), to - from);
            if (e->rom + e->length > pos + ROM_CHUNK) {
                break; // it goes on in the next chunk
            }
        }
        readTicks += t1 - t0;
        hashTicks += cpuGetTiming() - t1;
    }
    total = cpuEndTiming();
    DsiSha1Final(&sha, digest);
    free(scratch);

    HexDigest(hex, digest);
    DsiLog("read %d bytes from %s in %lu ms (read %lu, SHA-1 and copy %lu)\n", ROM_FILE_SIZE, path,
           (unsigned long)timerTicks2msec(total), (unsigned long)timerTicks2msec(readTicks),
           (unsigned long)timerTicks2msec(hashTicks));
    DsiLog("SHA-1 %s\n", hex);
    DsiLogFlush();
    if (memcmp(digest, sUsaSha1, 20) != 0) {
        HexDigest(hex, sUsaSha1);
        DsiLog("not the USA ROM: expected %s\n", hex);
        return false;
    }
    return true;
}

/*
 * Written under another name and renamed, so a write cut short never leaves a
 * gamedata.bin behind. A failure only means the ROM is read again next time.
 */
static void WriteGameData(size_t card, const uint8_t* sha1) {
    static uint8_t block[GAMEDATA_HEADER_SIZE];
    GameDataHeader* header = (GameDataHeader*)block;
    uint32_t size = __rom_copy_end - __rom_copy;
    const char* temp = sDataTempPaths[card];
    const char* path = sDataPaths[card];
    bool ok;
    FILE* file;

    memset(block, 0, sizeof(block));
    memcpy(header->magic, GAMEDATA_MAGIC, sizeof(GAMEDATA_MAGIC));
    header->format = GAMEDATA_FORMAT;
    header->headerSize = GAMEDATA_HEADER_SIZE;
    header->layout[0] = gRomLayoutVersion[0];
    header->layout[1] = gRomLayoutVersion[1];
    header->dataSize = size;
    memcpy(header->romSha1, sha1, sizeof(header->romSha1));

    cpuStartTiming(0);
    file = fopen(temp, "wb");
    ok = file != NULL;
    if (ok) {
        setvbuf(file, NULL, _IONBF, 0);
        ok = fwrite(block, 1, sizeof(block), file) == sizeof(block);
        for (uint32_t pos = 0; ok && pos < size;) {
            uint32_t length = size - pos < ROM_CHUNK ? size - pos : ROM_CHUNK;

            ok = fwrite(__rom_copy + pos, 1, length, file) == length;
            pos += length;
        }
        ok = fclose(file) == 0 && ok;
    }
    if (ok) {
        remove(path);
        ok = rename(temp, path) == 0;
    }
    if (!ok) {
        cpuEndTiming();
        remove(temp);
        DsiLog("could not write %s (is the card full?); the ROM is read again next time\n", path);
        return;
    }
    DsiLog("wrote %s in %lu ms; baserom.gba is only needed again for a build with other game data\n", path,
           (unsigned long)timerTicks2msec(cpuEndTiming()));
}

bool DsiRomLoad(void) {
    uint8_t digest[20];
    bool stale = false;

    if (!fatInitDefault()) {
        DsiLog("no SD card or DLDI device (fatInitDefault failed)\n");
        return false;
    }
    for (size_t card = 0; card < CARDS; card++) {
        DataResult result = LoadGameData(sDataPaths[card]);

        if (result == DATA_OK) {
            UseCard(card);
            return true;
        }
        stale |= result == DATA_STALE;
    }
    for (size_t card = 0; card < CARDS; card++) {
        FILE* file = fopen(sRomPaths[card], "rb");
        bool ok;

        if (file == NULL) {
            continue;
        }
        UseCard(card);
        DsiLog("making %s from %s\n", sDataPaths[card], sRomPaths[card]);
        DsiLogFlush();
        ok = ReadRom(file, sRomPaths[card], digest);
        fclose(file);
        if (ok) {
            WriteGameData(card, digest);
            DsiLogFlush();
        }
        return ok;
    }
    if (stale) {
        DsiLog("put your USA ROM at sd:/tmc/baserom.gba to make it again\n");
    } else {
        DsiLog("no game data: put your USA ROM at sd:/tmc/baserom.gba (needed once)\n");
    }
    DsiLogToDefaultFile();
    return false;
}

// Pointer words in data objects need not be word-aligned (data is 2-aligned).
static inline uint32_t LoadWord(const uint8_t* p) {
    uint32_t value;
    memcpy(&value, p, 4);
    return value;
}

static inline void StoreWord(uint8_t* p, uint32_t value) {
    memcpy(p, &value, 4);
}

// The next offset from a delta list, or false at its end.
static bool NextOffset(const uint16_t** p, const uint16_t* end, uint32_t* offset) {
    uint32_t step;

    if (*p >= end) {
        return false;
    }
    step = *(*p)++;
    if (step == 0) {
        step = (*p)[0] | ((uint32_t)(*p)[1] << 16);
        *p += 2;
    }
    *offset += step;
    return true;
}

/*
 * Each word is checked before it changes: it must hold the kind of GBA address
 * the generator found there, which the right ROM guarantees. A ROM data
 * address goes to its place in the copy (its extent's).
 */
bool DsiRomRelocate(void) {
    uint8_t* copy = __rom_copy;
    uint32_t size = __rom_copy_end - __rom_copy;
    uint32_t adds = 0, symbols = 0, kept = 0, unexpected = 0, offset;
    const uint16_t* p;

    p = gRomRelocAdds;
    offset = 0;
    while (NextOffset(&p, gRomRelocAddsEnd, &offset)) {
        uint8_t* target;

        if (offset > size - 4) {
            DsiLog("relocation at 0x%06lx is outside the copy\n", (unsigned long)offset);
            return false;
        }
        target = DsiRomPtr(LoadWord(copy + offset));
        if (target == NULL) {
            unexpected++;
        } else {
            StoreWord(copy + offset, (uint32_t)target);
        }
        adds++;
    }
    for (uint32_t i = 0; i < gRomRelocSymbolCount; i++) {
        uint32_t value = LoadWord(copy + gRomRelocSymbols[2 * i]);
        uint32_t region = value >> 24;

        // ROM, IWRAM, or a raw GBA hardware address (into its shadow).
        if (region != 0x08 && region != 0x09 && region != IWRAM_BASE >> 24 && (region < 0x04 || region > 0x07)) {
            unexpected++;
        }
        StoreWord(copy + gRomRelocSymbols[2 * i], gRomRelocSymbols[2 * i + 1]);
        symbols++;
    }
    p = gRomRelocKept;
    offset = 0;
    while (NextOffset(&p, gRomRelocKeptEnd, &offset)) {
        if (LoadWord(copy + offset) - EWRAM_BASE >= EWRAM_SIZE) {
            unexpected++;
        }
        kept++;
    }
    DC_FlushRange(copy, size);

    DsiLog("relocated: %lu add-base, %lu symbol; %lu EWRAM kept; %lu unexpected\n", (unsigned long)adds,
           (unsigned long)symbols, (unsigned long)kept, (unsigned long)unexpected);
    DsiLogFlush();
    if (adds != gRomRelocAddCount || kept != gRomRelocKeptCount) {
        DsiLog("expected %lu add-base and %lu EWRAM\n", (unsigned long)gRomRelocAddCount,
               (unsigned long)gRomRelocKeptCount);
        return false;
    }
    return unexpected == 0;
}

// The registers BlocksDS saved, into the log; PC is as saved (a data abort is
// 8 bytes past the faulting instruction, 4 in Thumb).
static void Exception(void) {
    const uint32_t* r = (const uint32_t*)exceptionRegisters;

    DsiLog("exception: pc %08lx lr %08lx sp %08lx\n", (unsigned long)r[15], (unsigned long)r[14],
           (unsigned long)r[13]);
    DsiFatal("r0 %08lx r1 %08lx r2 %08lx r3 %08lx", (unsigned long)r[0], (unsigned long)r[1],
             (unsigned long)r[2], (unsigned long)r[3]);
}

/*
 * Stray GBA ROM pointers must fault: on the DSi the GBA slot reads back 0xFF.
 * BlocksDS leaves 0x08000000-0x0AFFFFFF out of every MPU region, so an access
 * there is an abort; a region found over it is switched off.
 */
void DsiProtectGbaSlot(void) {
    static const uint32_t probes[] = { 0x08000000, 0x09000000, 0x0A000000, 0x0AFFFFFC };

    for (size_t i = 0; i < sizeof(probes) / sizeof(probes[0]); i++) {
        int region = mpuRegionGet(probes[i]);
        if (region >= 0) {
            DsiLog("MPU region %d (%08lx) covers 0x%08lx: off\n", region, (unsigned long)CP15_GetRegion(region),
                   (unsigned long)probes[i]);
            CP15_SetRegion(region, 0);
        }
    }
    setExceptionHandler(Exception);
    DsiLog("GBA slot unmapped (MPU)\n");
}
